<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";

export default {
  name: "PSLeaveReview",
  mixins: [processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      viewDrawer: false,
      loadingRequest: "",
      requestData: {
        loadingRequest: true,
        status: "",
      },
      url: "http://ihris.org/fhir/Questionnaire/ps-leave-approval",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/ps-leave-approval-profile",

      overlay: false,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      valid: false,
      submitting: false,
      dateMenu: false,

      // Confirmation dialog
      confirmDialog: false,
      confirmDialogTitle: "",
      confirmDialogMessage: "",
      confirmDialogIcon: { icon: "", color: "" },

      // Review form
      reviewDecision: null,
      reviewComments: "",
      actionDate: new Date().toISOString().substr(0, 10),

      // Rules
      rules: {
        required: (value) => !!value || "This field is required",
        minLength: (min) => (value) =>
          !value || value.length >= min || `Minimum ${min} characters required`,
      },
    };
  },

  computed: {
    isAlreadyReviewed() {
      return (
        this.requestData.status && this.requestData.status !== "underpsreview"
      );
    },
    canEdit() {
      return (
        this.requestData.status &&
        this.requestData.status === "psrejected" &&
        this.$moment().diff(this.$moment(this.actionDate), "days") <= 3
      );
    },

    editMode() {
      return !!this.fhirId;
    },

    leaveTypeSpecificComponent() {
      // Map leave type IDs to their detail components
      const componentMap = {
        study: "study-leave-details",
      };

      return componentMap[this.requestData.leaveTypeId] || null;
    },
  },

  async created() {
    this.loadingRequest = true;
    if (!this.queries.leave) {
      this.showSnackbar("No leave request ID provided", "error");
      this.loadingRequest = false;
      return;
    }

    // Check for existing PS review
    await this.checkExistingReview();
    this.loadingRequest = false;
  },

  methods: {
    async checkExistingReview() {
      try {
        const url = `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/ps-leave-approval-profile&leaverequest=${this.queries.leave}`;
        const response = await fetch(url);

        if (!response.ok) {
          console.log("No existing review found or error fetching");
          return;
        }

        const bundle = await response.json();
        if (!bundle.entry || bundle.entry.length === 0) {
          return;
        }

        // Found existing review - populate form
        const reviewResource = bundle.entry[0].resource;
        this.fhirId = reviewResource.id;

        const getExt = (url, type) => {
          const ext = reviewResource.extension?.find((e) =>
            e.url.includes(url),
          );
          return ext ? ext[type] : null;
        };

        // Populate form fields
        const statusCoding = getExt("review-status", "valueCoding");
        this.reviewDecision = statusCoding?.code || null;

        this.reviewComments = getExt("description", "valueString") || "";
        this.actionDate =
          getExt("action-date", "valueDate") ||
          new Date().toISOString().substr(0, 10);
      } catch (error) {
        console.error("Error checking for existing review:", error);
      }
    },

    populateRequestData(data) {
      Object.keys(data).forEach((key) => {
        this.$set(this.requestData, key, data[key]);
      });
    },

    quickApprove() {
      this.reviewDecision = "approved";
      this.reviewComments =
        "Approved. Leave dates are appropriate and team coverage is ensured.";
    },

    quickReject() {
      this.reviewDecision = "rejected";
      this.reviewComments = "";
      this.$nextTick(() => {
        const textarea = this.$el.querySelector("textarea");
        if (textarea) textarea.focus();
      });
    },

    submitReview() {
      this.$refs.form.validate();
      if (!this.valid) {
        this.showSnackbar("Please complete all required fields", "warning");
        return;
      }

      // Show confirmation dialog
      if (this.reviewDecision === "approved") {
        this.confirmDialogTitle = this.editMode
          ? "Confirm Update (Approve)"
          : "Confirm Approval";
        this.confirmDialogMessage = this.editMode
          ? "Are you sure you want to UPDATE your review to APPROVE this leave request?"
          : "Are you sure you want to APPROVE this leave request?";
        this.confirmDialogIcon = { icon: "mdi-check-circle", color: "success" };
      } else {
        this.confirmDialogTitle = this.editMode
          ? "Confirm Update (Reject)"
          : "Confirm Rejection";
        this.confirmDialogMessage = this.editMode
          ? "Are you sure you want to UPDATE your review to REJECT this leave request?"
          : "Are you sure you want to REJECT this leave request? This action cannot be undone.";
        this.confirmDialogIcon = { icon: "mdi-close-circle", color: "error" };
      }

      this.confirmDialog = true;
    },

    async confirmSubmit() {
      this.confirmDialog = false;
      this.submitting = true;
      this.overlay = true;

      try {
        // Build FHIR data
        this.fhir = {
          reviewDecision: this.reviewDecision,
          reviewDecisionDisplay:
            this.reviewDecision == "approved" ? "Approved" : "Rejected",
          description: this.reviewComments,
          actionDate: this.actionDate,
        };

        await this.processFHIR();

        this.showSnackbar(
          this.editMode
            ? "Review updated successfully!"
            : "Review submitted successfully!",
          "success",
        );

        // Refresh the review data
        this.loadLeaveRequest = true;
        await this.$refs.leaveDetailsDisplay.loadLeaveRequest();
        await this.checkExistingReview();
        this.loadLeaveRequest = false;
      } catch (error) {
        console.error("Error submitting review:", error);
        this.showSnackbar("Error submitting review", "error");
      } finally {
        this.submitting = false;
        this.overlay = false;
      }
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/my-tasks");
      }
    },
  },

  components: {
    "leave-details-display": () => import("./extra-view/leave-details-display"),
    "study-leave-details": () => import("./extra-view/study-leave"),
    // Add more leave type detail components as needed
  },
};
</script>

